    -- --------------------------------------------------------------------------
    -- Artículo: Mis Nuevos Vecinos (ID: b50797a4-7cfd-47e8-aaf5-f85627cb7f7c)
    -- --------------------------------------------------------------------------
    INSERT INTO articulos (id, autor_id, categoria_id, titulo, slug, contenido, extracto, imagen_destacada, estado, etiquetas, metadata, created_at, updated_at)
    VALUES (
        'b50797a4-7cfd-47e8-aaf5-f85627cb7f7c',
        target_admin_id,
        NULL,
        'Mis Nuevos Vecinos',
        'mis-nuevos-vecinos',
        '<h2>📜 Descripción de Mis Nuevos Vecinos</h2><p><strong>Mis Nuevos Vecinos</strong> es una dinámica rompehielos de integración y rompecabezas social muy divertida para el inicio de campamentos o jornadas de grupo. Permite aprender y memorizar rápidamente los nombres de los compañeros mientras se estimulan los reflejos y la atención constante en un ambiente alegre.</p><hr><h3>🎲 ¿Cómo se juega a Mis Nuevos Vecinos?</h3><ol><li><strong>Disposición Inicial:</strong> Los participantes se sientan en un círculo de sillas. Se ubica una silla menos que la cantidad de jugadores presentes. El animador o jugador que inicia se ubica de pie en el centro sin silla.</li><li><strong>La Pregunta Clave:</strong> El participante del centro se acerca a un compañero sentado y le pregunta en voz alta: <em>«¿Te gustan tus vecinos?»</em>.</li><li><strong>Respuesta "NO" (Intercambio Elegido):</strong> Si responde <strong>«NO»</strong>, debe nombrar inmediatamente a dos personas del círculo con quienes le gustaría vivir como sus nuevos vecinos de derecha e izquierda. Los vecinos actuales a sus lados deben ponerse de pie para ceder sus puestos, mientras las dos personas nombradas corren a ocupar las sillas vacías. En ese instante de movimiento, la persona del centro intenta sentarse en cualquier silla desocupada. Quien se quede sin silla pasa al centro para reiniciar la dinámica.</li><li><strong>Respuesta "SÍ" (Rotación de Sillas):</strong> Si responde <strong>«SÍ»</strong>, todo el grupo debe levantarse e inmediatamente rotar una silla a la derecha. Al escuchar el tercer «SÍ» del juego, rotan dos sillas a la derecha; al cuarto «SÍ», dos sillas a la izquierda, generando giros sorpresivos y mucha diversión.</li></ol>',
        'Una dinámica rompehielos scout ideal para aprender nombres, agilizar reflejos y fomentar la fraternidad grupal.',
        '/uploads/mis-nuevos-vecinos.webp',
        'publicado',
        ARRAY['dinamica','presentacion','rompehielos','nombres','integracion']::text[],
        '{"areas": ["sociabilidad", "afectividad"], "lugares": ["Interior", "Exterior"], "cantidad": "06 participantes", "duracion": "15 minutos", "unidades": ["manada", "compañía", "tropa"], "descargas": [], "objetivos": ["Conocer a los demás", "Crear un ambiente de distensión", "Estimular la atención a los detalles", "Favorecer la comunicación en el grupo"], "materiales": ["Sillas"], "variaciones": "<b>Sillas con Pañolines:</b> En lugar de sillas fijas, se colocan pañolines scouts sobre el césped como marcas de puesto.\n\n<b>Vecinos por Atributos:</b> En lugar de nombres personales, se nombran características scouts (ej. mis nuevos vecinos son quienes llevan pañolín bicolor).", "recomendaciones": "<b>Espacio Seguro:</b> Mantener las sillas con espacio suficiente en la espalda para evitar tropiezos durante los giros rítmicos.\n\n<b>Inclusión Activa:</b> Guiar sutilmente las elecciones del centro para que todas las niñas y niños sean nombrados e integrados por igual.\n\n<b>Clima de Alegría:</b> Fomentar que las respuestas y giros se realicen con entusiasmo sin empujones.", "justificacion_areas": "Mis Nuevos Vecinos promueve la <b>sociabilidad</b> y la <b>afectividad</b> mediante la interacción empática y desinhibida entre pares. La mecánica de memorizar nombres y reaccionar con respeto ante los cambios de grupo fortalece los lazos de amistad, la asertividad y el sentido de acogida comunitaria.", "objetivos_educativos": [{"id": "36b44b5b-601f-4d7f-a510-8266479c9da1", "area": "Afectividad", "texto": "Me gusta tener nuevos amigos y amigas.", "unidad": "Manada", "como_se_cumple": "Integrándome con entusiasmo al grupo y compartiendo el juego de presentación con mis compañeros."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "unidad": "Manada", "como_se_cumple": "Respetando las reglas de rotación de sillas y los turnos al momento de ser nombrado en el centro."}, {"id": "9f8cdd1f-20d5-47f8-92c2-a660693c348f", "area": "Afectividad", "texto": "Soy cada vez más amigo de mis amigos y amigas, pero igual aprecio a mis demás compañeros.", "unidad": "Manada", "como_se_cumple": "Valorando y memorizando con respeto los nombres de todos los integrantes de la unidad."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "unidad": "Manada", "como_se_cumple": "Cediendo el puesto con fair play cuando mis vecinos son llamados a intercambiar posición."}, {"id": "c41ebefe-da04-4671-a854-40d544b6366e", "area": "Afectividad", "texto": "Soy leal con mis amigas y amigos sin dejar de lado o tratar mal a quienes no lo son.", "unidad": "Compañía", "como_se_cumple": "Invitando alegremente a distintas compañeras a ser mis nuevas vecinas de grupo."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Compañía", "como_se_cumple": "Cumpliendo de forma ordenada las rotaciones a la derecha o izquierda según el conteo de respuestas."}, {"id": "0be7336d-2934-49dd-95c1-3d881a510463", "area": "Afectividad", "texto": "Aprecio a mis amigos y amigas y no me enojo con ellos por cosas cualquier cosa.", "unidad": "Compañía", "como_se_cumple": "Reaccionando con alegría y camaradería ante los cambios de silla durante la dinámica."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Compañía", "como_se_cumple": "Manteniendo el clima de juego limpio y de seguridad al correr hacia las sillas vacías."}, {"id": "34b68e26-4ce0-43e1-b45a-0b41336af495", "area": "Afectividad", "texto": "Soy leal con mis amigos y amigos sin dejar de lado o tratar mal a quienes no lo son.", "unidad": "Tropa", "como_se_cumple": "Acogiendo con fraternidad scout a todos los compañeros al rotar de vecinos."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Tropa", "como_se_cumple": "Aceptando democráticamente la dinamización del espacio y las instrucciones del líder."}, {"id": "3693aeed-e3ad-4ac9-878c-5874b61dc8d3", "area": "Afectividad", "texto": "Aprecio a mis amigos y amigos y no me enojo con ellos por cosas cualquier cosa.", "unidad": "Tropa", "como_se_cumple": "Disfrutando la sana competencia y respetando los turnos de juego de forma limpia."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Tropa", "como_se_cumple": "Participando activamente en la convivencia fraterna de la patrulla y la tropa."}]}'::jsonb,
        '2026-07-26T06:37:03.021726+00:00',
        NOW()
    )
