    -- --------------------------------------------------------------------------
    -- Artículo: El Amigo Secreto Scout (ID: 239e918e-324d-4302-81d2-611d80e0a62e)
    -- --------------------------------------------------------------------------
    INSERT INTO articulos (id, autor_id, categoria_id, titulo, slug, contenido, extracto, imagen_destacada, estado, etiquetas, metadata, created_at, updated_at)
    VALUES (
        '239e918e-324d-4302-81d2-611d80e0a62e',
        target_admin_id,
        NULL,
        'El Amigo Secreto Scout',
        'el-amigo-secreto-scout',
        '<h2>📜 Descripción de El Amigo Secreto Scout</h2><p><strong>El Amigo Secreto Scout</strong> es una vivencia fraterna de integración y afectividad diseñada para fortalecer los lazos de confianza, aprecio mutuo y observación atenta entre los integrantes de la unidad. A través de gestos anónimos de constante atención, compañerismo y cartas secretas redactadas con sincero afecto, los participantes aprenden a valorar las virtudes y cualidades únicas de cada uno de sus pares.</p><h2>🎲 ¿Cómo se juega <strong>El Amigo Secreto Scout</strong>?</h2><h3>1. Asignación Secreta</h3><p>Cada participante extrae al azar el nombre de un compañero de la unidad, quien se convertirá en su <strong>Amigo Secreto</strong>. El nombre asignado se mantiene en estricto secreto durante todo el ciclo de la dinámica.</p><h3>2. Observación Atenta y Acciones Fraternas</h3><p>Durante un período determinado (varios días de campamento o entre reuniones semanales), cada participante observa con atención las virtudes, fortalezas y momentos significativos de su amigo secreto, realizando pequeños actos anónimos de servicio (como dejar notas de aliento en su pañolín o mochila).</p><h3>3. Redacción de la Carta Fraterna</h3><p>Al finalizar el período, cada scout escribe una carta personal detallando las cualidades positivas observadas, las virtudes demostradas en el grupo y palabras sinceras de aprecio scout.</p><h3>4. Revelación y Abrazo Scout</h3><p>En un ambiente cálido en torno a la fogata o al término de una reunión de unidad, cada participante lee su carta ante el grupo y revela la identidad de su amigo secreto con un fraterno abrazo scout.</p>',
        'Dinámica fraterna para desarrollar la confianza, el aprecio mutuo y la sociabilidad mediante la observación de virtudes y cartas secretas.',
        '/uploads/el-amigo-secreto-scout.webp',
        'publicado',
        ARRAY['juego','cooperativo','confianza','afectividad','sociabilidad']::text[],
        '{"areas": ["sociabilidad", "afectividad", "carácter"], "lugares": ["Interior", "Exterior"], "cantidad": "04 participantes", "duracion": "30 minutos", "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "descargas": [], "objetivos": ["Conocer a los demás", "Estimular la confianza", "Fomentar las relaciones interpersonales", "Reforzar lazos sociales"], "materiales": ["Papel", "Lápices", "Sobres"], "variaciones": "<b>Variación Campamento:</b> Durante el campamento de verano, cada amigo secreto puede dejar pequeñas sorpresas anónimas en la tienda de su compañero (como flores de campo o notas de aliento).<br><b>Variación con Pañolín:</b> Al momento de la revelación, el amigo secreto coloca suavemente el pañolín sobre el hombro de su compañero como símbolo de fraternidad scout.", "recomendaciones": "<b>Rol de la Jefatura:</b> Asegurar que ningún participante quede sin amigo secreto y supervisar que las cartas resalten aspectos positivos, promoviendo siempre el respeto y la autoestima.<br><b>Ambiente Cálido:</b> Realizar el cierre en un círculo acogedor, permitiendo que cada participante exprese cómo se sintió al recibir y entregar las muestras de afecto.", "justificacion_areas": "Esta dinámica ejercita de manera directa y profunda tres áreas clave del desarrollo scout:\n1. <b>Afectividad:</b> Permite a los participantes expresar aprecio sincero y afecto desinteresado por sus pares mediante cartas y notas anónimas, fortaleciendo la autoestima y la salud emocional.\n2. <b>Sociabilidad:</b> Promueve la integración fraterna y el derribo de barreras de exclusión en la unidad, enseñando a valorar la convivencia, el respeto por las normas de grupo y los lazos sociales.\n3. <b>Carácter:</b> Desarrolla la empatía, la perseverancia en la atención discreta a los demás, la honestidad y la madurez personal para reconocer y felicitar las virtudes ajenas sin buscar protagonismo personal.", "objetivos_educativos": [{"id": "b39109f4-260d-46e2-9192-2db4de116b1b", "area": "Afectividad", "texto": "Converso y comparto con todas las personas.", "unidad": "Manada", "como_se_cumple": "Conversando y compartiendo mi alegría con todos mis compañeros de la Manada sin hacer distinción."}, {"id": "b658a9a2-c0fb-4aec-b862-528eb90e07d1", "area": "Afectividad", "texto": "Comparto con todos mis compañeros, sin importarme su raza, en qué trabajan sus papás, o si tienen o no dinero.", "unidad": "Manada", "como_se_cumple": "Acogiendo con entusiasmo a cualquier compañero que me haya tocado en el sorteo de la Manada."}, {"id": "1999e4c0-935b-4134-95be-92f01a5edf81", "area": "Afectividad", "texto": "Me intereso por las demás personas y soy generosa.", "unidad": "Compañía", "como_se_cumple": "Demostrando mi generosidad y preocupación constante por las vivencias de mi amiga secreta."}, {"id": "80ff5a70-cc39-4599-99b1-38aa13b44f49", "area": "Afectividad", "texto": "Aprecio a las personas por lo que son.", "unidad": "Compañía", "como_se_cumple": "Expresando en mi carta fraterna las virtudes auténticas de mi compañera de patrulla."}, {"id": "70177516-c52f-4e19-8c59-32375c40eaac", "area": "Afectividad", "texto": "Me intereso por los demás personas y soy generoso.", "unidad": "Tropa", "como_se_cumple": "Observando atentamente las buenas acciones de mi hermano scout para destacarlas en mi mensaje secreto."}, {"id": "28433366-23af-4d9a-a8c6-fbca64ef0c95", "area": "Afectividad", "texto": "Estoy siempre dispuesto a ayudar a mis compañeros de patrulla.", "unidad": "Tropa", "como_se_cumple": "Brindando mi ayuda desinteresada y servicio diario a mis compañeros durante el campamento."}, {"id": "edfc3452-910a-4b7b-bcc5-73628cf20c0a", "area": "Afectividad", "texto": "Comparto y defiendo el derecho de los demás a ser valorados por lo que son y no por lo que tienen.", "unidad": "Avanzada", "como_se_cumple": "Defendiendo el respeto mutuo y la valoración auténtica entre todos los integrantes de mi avanzada."}, {"id": "39de3f68-3477-4c1f-8a29-170e914596d7", "area": "Afectividad", "texto": "Construyo mi felicidad personal en el amor, sirviendo a los otros sin esperar recompensa y valorándolos por lo que son.", "unidad": "Clan", "como_se_cumple": "Viviendo la fraternidad scout como un servicio desinteresado de afecto y apoyo incondicional."}, {"id": "99c6e695-ef0b-4e36-956b-3faf15ada355", "area": "Carácter", "texto": "Escucho a los demás lobatos, a mis papás y a mis dirigentes y guiadoras.", "unidad": "Manada", "como_se_cumple": "Escuchando con atención y afecto a los demás lobatos durante el círculo de revelación."}, {"id": "6b8c5fb5-6730-4c61-a332-2a7e6033bd94", "area": "Carácter", "texto": "Me llevo bien con todos los lobatos de la Manada.", "unidad": "Manada", "como_se_cumple": "Promoviendo el buen trato y la amistad fraterna con todos los lobatos de mi seisenas."}, {"id": "81cd6596-30cd-40fe-83e8-c86bf12a21f2", "area": "Carácter", "texto": "Aprecio los consejos que me dan en mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Apreciando las palabras de aliento y reflexiones compartidas por mis compañeras."}, {"id": "0da6c9df-7a09-44cd-9961-e06c0173d41a", "area": "Carácter", "texto": "Ayudo a mis compañeras de patrulla a superarse.", "unidad": "Compañía", "como_se_cumple": "Ayudando discretamente a mis compañeras de patrulla a destacar sus fortalezas personales."}, {"id": "0969a204-e8c6-4ab6-ac4f-c777bae066df", "area": "Carácter", "texto": "Aprecio los consejos que me dan en mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Recibiendo con humildad y madurez las opiniones positivas de mis hermanos scouts."}, {"id": "f608eb2d-613a-477a-86f9-03e769a87bf2", "area": "Carácter", "texto": "Ayudo a mis compañeros de patrulla a superarse.", "unidad": "Tropa", "como_se_cumple": "Motivando a mis compañeros de patrulla a superar sus dificultades mediante gestos solidarios."}, {"id": "db877208-738b-4e2e-bcbc-591331f75703", "area": "Carácter", "texto": "Reconozco en mi Avanzada una comunidad de vida y acepto las críticas y recomendaciones que mis compañeros y compañeras me hacen.", "unidad": "Avanzada", "como_se_cumple": "Reconociendo en mi avanzada un espacio seguro de crecimiento y valoración personal."}, {"id": "8df0eaed-f805-4347-881d-3d5fac18c8a5", "area": "Carácter", "texto": "Reconozco en mi grupo de pertenencia un apoyo para mi crecimiento personal y para la realización de mi proyecto de vida.", "unidad": "Clan", "como_se_cumple": "Encontrando en la comunidad de clan el testimonio fraterno para fortalecer mi proyecto de vida."}, {"id": "88ecaf2b-fa30-45c3-9248-3ad08306471d", "area": "Sociabilidad", "texto": "Colaboro en lo que puedo en campañas de ayuda a los que más lo necesitan.", "unidad": "Manada", "como_se_cumple": "Colaborando con alegría en las pequeñas muestras anónimas de afecto para mi amigo secreto de la Manada."}, {"id": "d5415bd4-83bf-4a22-aeaf-9926b88f9b00", "area": "Sociabilidad", "texto": "Participo siempre en campañas de ayuda a quienes lo necesitan.", "unidad": "Manada", "como_se_cumple": "Participando entusiasmado en las notas de servicio y aprecio para mi compañero de la seisena."}, {"id": "edd3b4b5-1096-44fe-8b8b-7364449cd520", "area": "Sociabilidad", "texto": "Trato de realizar una buena acción todos los días.", "unidad": "Compañía", "como_se_cumple": "Realizando mi buena acción diaria orientada al bienestar de mi amiga secreta en la patrulla."}, {"id": "b98c1bb4-08e3-4310-bda4-793552993138", "area": "Sociabilidad", "texto": "Realizo una buena acción cada día.", "unidad": "Compañía", "como_se_cumple": "Dedicando gestos concretos de aprecio y servicio secreto a mi compañera durante la unidad."}, {"id": "16388e31-ed8c-443f-9881-4dea357f2edd", "area": "Sociabilidad", "texto": "Trato de realizar una buena acción todos los días.", "unidad": "Tropa", "como_se_cumple": "Buscando diariamente oportunidades discretas de servicio y aliento para mi hermano scout."}, {"id": "8a38e69e-7013-4ec8-8112-181f68e4224a", "area": "Sociabilidad", "texto": "Realizo una buena acción cada día.", "unidad": "Tropa", "como_se_cumple": "Realizando con constancia acciones fraternas de servicio para mi amigo secreto de la patrulla."}, {"id": "6ad49405-62ca-4a55-9d9e-78f1a48337d7", "area": "Sociabilidad", "texto": "Participo activamente en las campañas de servicio y desarrollo de la comunidad que organiza mi Grupo o mi Asociación.", "unidad": "Avanzada", "como_se_cumple": "Promoviendo el servicio fraterno y la integración activa dentro de la avanzada."}, {"id": "f47192a7-6d68-4a3a-9847-8d1c29f7ba49", "area": "Sociabilidad", "texto": "Sirvo activamente en mi comunidad local, contribuyendo a crear una sociedad justa, participativa y fraterna.", "unidad": "Clan", "como_se_cumple": "Viviendo el servicio scout como un hábito constante de desarrollo comunitario y fraternidad en el Clan."}]}'::jsonb,
        '2026-07-27T21:23:38.584367+00:00',
        NOW()
    )
