    -- --------------------------------------------------------------------------
    -- Artículo: Los Magos de Teis (ID: 6a6e0efc-1034-47f6-89a8-39190903baa3)
    -- --------------------------------------------------------------------------
    INSERT INTO articulos (id, autor_id, categoria_id, titulo, slug, contenido, extracto, imagen_destacada, estado, etiquetas, metadata, created_at, updated_at)
    VALUES (
        '6a6e0efc-1034-47f6-89a8-39190903baa3',
        target_admin_id,
        NULL,
        'Los Magos de Teis',
        'los-magos-de-teis',
        '<h2>📜 Descripción de Los Magos de Teis</h2><p> </p><p><strong>Los Magos de Teis</strong> es una gran dinámica de puestos y misiones de exterior donde tres equipos (los Hechiceros de la Tuak, los Consejeros de Teis y los Aventis) interactúan resolviendo pruebas creativas, trabajo en equipo y desafíos de destreza para liberar a los prisioneros del pueblo y alcanzar el bien común de la tribu.</p><p> </p><h2>🎲 ¿Cómo se juega Los Magos de Teis?</h2><p> </p><h3>1. Roles y Misiones de Unidad</h3><p> </p><p>Se dividen los participantes en tres grandes equipos con roles y funciones complementarias: los Hechiceros (diseñadores de pruebas), los Consejeros (jueces y guías del pueblo) y los Aventis (los exploradores que deben superar los desafíos).</p><p> </p><h3>2. Superación de Pruebas de Puesto</h3><p> </p><p>Los Aventis recorren los distintos puestos de la base realizando las misiones asignadas por los Hechiceros, tales como construcción de herramientas, resolución de enigmas y elaboración de vestimentas o pañolines de la tribu.</p><p> </p><h3>3. Evaluación del Consejo</h3><p> </p><p>Al completar cada estación, los Consejeros revisan el cumplimiento de las metas, entregando sugerencias constructivas y desbloqueando las pistas necesarias para liberar a los prisioneros.</p><p> </p><h3>4. Liberación Fraterna</h3><p> </p><p>Una vez completadas todas las pruebas, los equipos se reúnen en el centro del pueblo para celebrar la libertad de los prisioneros y compartir los aprendizajes del día.</p>',
        'Juego de puestos y misiones de exterior donde tres equipos colaboran superando pruebas para liberar a los prisioneros de la tribu.',
        '/uploads/los-magos-de-teis.webp',
        'publicado',
        ARRAY['juego','exterior','cooperativo','caracter','estrategia']::text[],
        '{"areas": ["carácter"], "lugares": ["Exterior", "campo abierto"], "cantidad": "12 participantes", "duracion": "60 minutos", "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "descargas": [], "objetivos": ["Trabajo en equipo", "Construcción de Equipos", "Estrategia y planificación", "Favorecer el trabajo en equipo"], "materiales": ["Cartones", "Tijeras", "Cuerdas", "Retazos de Tela", "Pañolines"], "variaciones": "<b>Variación de Campamento:</b> Se pueden incluir estaciones nocturnas iluminadas con antorchas o linternas para aumentar la ambientación mística.<br /></br /><b>Variación con Pañolín:</b> Cada equipo elabora un pañolín representativo de su tribu utilizando retazos de tela y cuerdas.", "recomendaciones": "<b>Ambientación de Jefatura:</b> Los dirigentes y guiadoras deben asumir roles caracterizados como sabios Hechiceros para enriquecer el marco simbólico.<br/><br/><b>Supervisión de Seguridad:</b> Delimitar claramente las zonas de puesto en el campo abierto.", "justificacion_areas": "Este juego ejercita de manera directa y profunda el área de Carácter:\n1. <b>Carácter:</b> Fomenta la pertenencia al grupo, el acatamiento consciente de las normas democráticas del grupo, la colaboración desinteresada y el liderazgo fraterno para resolver desafíos colectivos sin buscar protagonismos individuales.", "objetivos_educativos": [{"id": "99c6e695-ef0b-4e36-956b-3faf15ada355", "area": "Carácter", "texto": "Escucho a los demás lobatos, a mis papás y a mis dirigentes y guiadoras.", "unidad": "Manada", "como_se_cumple": "Escuchando con atención las instrucciones de los Viejos Lobos durante el recorrido por los puestos del juego."}, {"id": "6b8c5fb5-6730-4c61-a332-2a7e6033bd94", "area": "Carácter", "texto": "Me llevo bien con todos los lobatos de la Manada.", "unidad": "Manada", "como_se_cumple": "Colaborando alegremente en la seiscena para superar juntos cada prueba asignada por el consejo."}, {"id": "81cd6596-30cd-40fe-83e8-c86bf12a21f2", "area": "Carácter", "texto": "Aprecio los consejos que me dan en mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Aceptando con madurez las sugerencias de los Consejeros para mejorar la estrategia de la patrulla."}, {"id": "0da6c9df-7a09-44cd-9961-e06c0173d41a", "area": "Carácter", "texto": "Ayudo a mis compañeras de patrulla a superarse.", "unidad": "Compañía", "como_se_cumple": "Apoyando a mis compañeras en la confección de vestimentas y resolución de pruebas de equipo."}, {"id": "0969a204-e8c6-4ab6-ac4f-c777bae066df", "area": "Carácter", "texto": "Aprecio los consejos que me dan en mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Recibiendo las recomendaciones de los puestos con espíritu de superación scout."}, {"id": "f608eb2d-613a-477a-86f9-03e769a87bf2", "area": "Carácter", "texto": "Ayudo a mis compañeros de patrulla a superarse.", "unidad": "Tropa", "como_se_cumple": "Motivando a mi patrulla a mantener la unión y el trabajo coordinado en cada base del juego."}, {"id": "db877208-738b-4e2e-bcbc-591331f75703", "area": "Carácter", "texto": "Reconozco en mi Avanzada una comunidad de vida y acepto las críticas y recomendaciones que mis compañeros y compañeras me hacen.", "unidad": "Avanzada", "como_se_cumple": "Asumiendo el rol de liderazgo y facilitación en los puestos de la avanzada con responsabilidad."}, {"id": "8df0eaed-f805-4347-881d-3d5fac18c8a5", "area": "Carácter", "texto": "Reconozco en mi grupo de pertenencia un apoyo para mi crecimiento personal y para la realización de mi proyecto de vida.", "unidad": "Clan", "como_se_cumple": "Fortaleciendo la vida en comunidad y el trabajo fraterno para alcanzar las metas colectivas del Clan."}]}'::jsonb,
        '2026-07-27T22:44:41.725831+00:00',
        NOW()
    )
