    -- --------------------------------------------------------------------------
    -- Artículo: Entrevistémonos (ID: 1eb1be54-afe5-4f94-af87-519b365d3961)
    -- --------------------------------------------------------------------------
    INSERT INTO articulos (id, autor_id, categoria_id, titulo, slug, contenido, extracto, imagen_destacada, estado, etiquetas, metadata, created_at, updated_at)
    VALUES (
        '1eb1be54-afe5-4f94-af87-519b365d3961',
        target_admin_id,
        NULL,
        'Entrevistémonos',
        'entrevistemonos',
        '<h2>📜 Descripción de la Dinámica Entrevistémonos</h2><p> </p><p><strong>Entrevistémonos</strong> es una dinámica de integración, confianza y conocimiento interpersonal diseñada para formar parejas entre participantes que no interactúan habitualmente. A través de un espacio de diálogo fraterno y reflexivo, los participantes comparten sus vivencias, fortalezas y metas para construir un espacio de confianza recíproca.</p><p> </p><h2>🎲 ¿Cómo se juega Entrevistémonos?</h2><p> </p><h3>1. Formación de Parejas Fraternas</h3><p> </p><p>Los participantes se agrupan en parejas, priorizando reunirse con compañeros de la unidad con quienes compartan menos en las actividades cotidianas.</p><p> </p><h3>2. Diálogo Personal Aislado</h3><p> </p><p>Cada pareja busca un espacio tranquilo del terreno de juego. Durante 10 minutos por turno (20 minutos en total), cada participante entrevista al otro y comparte sus experiencias, proyectos personales y formas de ver la vida.</p><p> </p><h3>3. Registro e Intercambio de Aliento</h3><p> </p><p>Con respeto y atención activa, cada scout toma nota de las virtudes y sueños compartidos por su compañero, redactando un breve mensaje de aliento scout.</p><p> </p><h3>4. Puesta en Común y Cierre</h3><p> </p><p>De regreso en el gran círculo de unidad, cada participante presenta ante el grupo a su compañero destacando sus mejores cualidades y fortalezas.</p>',
        'Dinámica de integración en parejas para fortalecer la confianza, la comunicación abierta y el conocimiento entre los integrantes de la unidad.',
        '/uploads/entrevistemonos.webp',
        'publicado',
        ARRAY['dinámica','afectividad','sociabilidad','confianza','integracion']::text[],
        '{"areas": ["afectividad", "sociabilidad"], "lugares": ["Exterior", "campo abierto"], "cantidad": "02 participantes", "duracion": "20 minutos", "unidades": ["compañía", "tropa", "avanzada", "clan"], "descargas": [], "objetivos": ["Facilitar el conocimiento entre los pares", "Estimular la confianza", "Favorecer la comunicación en el grupo", "Fomentar las relaciones interpersonales"], "materiales": ["Papel", "Lápices"], "variaciones": "<b>Variación por Rondas Veloces:</b> Se pueden realizar entrevistas breves de 3 minutos cambiando de pareja en cada señal para acelerar el contacto inicial entre todos los integrantes.<br><b>Variación con Objeto Significativo:</b> Cada participante lleva consigo un objeto personal querido y explica su historia a su compañero como disparador del diálogo.", "recomendaciones": "<b>Facilitación Dirigente:</b> Velar por un ambiente de serenidad y escucha atenta, sugiriendo preguntas guía en caso de que a alguna pareja le cueste romper el hielo inicial.<br><b>Formación Inclusiva:</b> Organizar las parejas buscando intencionadamente juntar a miembros que tengan menos afinidad o convivencia habitual.", "justificacion_areas": "Esta dinámica ejercita de manera directa y profunda las áreas de Afectividad y Sociabilidad al promover la comunicación asertiva, la empatía y el respeto por la igual dignidad de los demás, fortaleciendo los lazos sociales y la tolerancia interpersonal dentro de la unidad.", "objetivos_educativos": [{"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "unidad": "Compañía", "como_se_cumple": "Escuchando con atención activa y respeto el testimonio y vivencias compartidas por mi compañera de patrulla."}, {"id": "672a5da0-8cab-42bb-85dd-0d1f285a1b91", "area": "Afectividad", "texto": "Digo lo que pienso con respeto hacia las demás personas.", "unidad": "Compañía", "como_se_cumple": "Expresando mis reflexiones y apreciaciones con calidez y honestidad al entrevistar a mi compañera."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "unidad": "Tropa", "como_se_cumple": "Acogiendo con apertura y sin prejuicios las vivencias contadas por mi hermano scout."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "unidad": "Tropa", "como_se_cumple": "Comunicando abiertamente mis pensamientos y escuchando con empatía a mi compañero durante el diálogo."}, {"id": "6c2b5054-70e8-4529-957f-a8abea073918", "area": "Afectividad", "texto": "Expreso mis opiniones libremente, sin descalificar a los demás.", "unidad": "Avanzada", "como_se_cumple": "Debatiendo y compartiendo ideales con altura de miras e integración franca en la avanzada."}, {"id": "d0ba748f-313b-4ffe-b2a3-fb21c1f8943f", "area": "Afectividad", "texto": "Practico una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "unidad": "Clan", "como_se_cumple": "Practicando una comunicación asertiva, empática y de fraternidad profunda entre los miembros del Clan."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "unidad": "Compañía", "como_se_cumple": "Promoviendo el respeto y la aceptación activa de las diferencias individuales de mis compañeras."}, {"id": "ea86ecee-b201-4a49-be9d-4e55de7ffe8c", "area": "Sociabilidad", "texto": "Respeto a todas las personas, independientemente de sus ideas, su clase social y su forma de vida.", "unidad": "Compañía", "como_se_cumple": "Valorando con apertura y tolerancia la diversidad de opiniones y realidades dentro de la patrulla."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "unidad": "Tropa", "como_se_cumple": "Fomentando un clima fraterno de integración y buen trato con todos los miembros de la tropa."}, {"id": "9e3ce0d2-2b56-4d1e-9135-029cfaaa0e6b", "area": "Sociabilidad", "texto": "Respeto a todas las personas, independientemente de sus ideas, su clase social y su forma de vida.", "unidad": "Tropa", "como_se_cumple": "Demostrando tolerancia y respeto por las perspectivas y vivencias de mis hermanos scouts."}, {"id": "007591fb-a2b6-4fb5-9286-acde65455f53", "area": "Sociabilidad", "texto": "Creo que todas las personas somos iguales en dignidad y eso marca mis relaciones con los demás.", "unidad": "Avanzada", "como_se_cumple": "Reconociendo la igual dignidad de cada joven y fortaleciendo las relaciones interpersonales de la avanzada."}, {"id": "b5a81328-5c07-41bd-a1ea-1ed401762841", "area": "Sociabilidad", "texto": "Vivo mi libertad de un modo solidario, ejerciendo mis derechos, cumpliendo mis obligaciones y defendiendo igual derecho para los demás.", "unidad": "Clan", "como_se_cumple": "Viviendo las relaciones humanas desde la solidaridad, el respeto de los derechos mutuos y la fraternidad scout en el Clan."}]}'::jsonb,
        '2026-07-27T23:18:05.939039+00:00',
        NOW()
    )
