    -- --------------------------------------------------------------------------
    -- Artículo: Pelota al Vuelo (ID: f5a2b357-79b2-4bcb-8beb-e41996c0668e)
    -- --------------------------------------------------------------------------
    INSERT INTO articulos (id, autor_id, categoria_id, titulo, slug, contenido, extracto, imagen_destacada, estado, etiquetas, metadata, created_at, updated_at)
    VALUES (
        'f5a2b357-79b2-4bcb-8beb-e41996c0668e',
        target_admin_id,
        NULL,
        'Pelota al Vuelo',
        'pelota-al-vuelo',
        '<h2>📜 Descripción de Pelota al Vuelo</h2><p> </p><p><strong>Pelota al Vuelo</strong> es un dinámico juego de reacción rápida, coordinación y memoria de nombres. La unidad se dispone en un gran círculo donde un participante lanza una pelota al aire desde el centro mientras nombra a un compañero, quien debe reaccionar velozmente para atraparla antes de que toque el suelo.</p><p> </p><h2>🎲 ¿Cómo se juega Pelota al Vuelo?</h2><p> </p><h3>1. Formación del Círculo Inicial</h3><p> </p><p>Todos los participantes se ubican de pie formando un gran círculo. Un scout ingresa al centro sosteniendo la pelota o balón.</p><p> </p><h3>2. Lanzamiento y Llamado</h3><p> </p><p>El jugador del centro lanza la pelota verticalmente hacia el aire y grita fuerte el nombre de un compañero del círculo, regresando inmediatamente a su lugar.</p><p> </p><h3>3. Reacción y Recepción</h3><p> </p><p>El participante nombrado debe correr al centro y atrapar la pelota en el aire o tras el primer bote antes de que se detenga.</p><p> </p><h3>4. Continuidad del Juego</h3><p> </p><p>Quien atrapa la pelota asume el rol del centro, lanzándola nuevamente y nombrando a un nuevo compañero que aún no haya sido llamado, hasta integrar a todo el grupo.</p>',
        'Juego dinámico en círculo de agilidad y reflejos donde los participantes lanzan la pelota nombrando a un compañero para atraparla en el aire.',
        '/uploads/pelota-al-vuelo.webp',
        'publicado',
        ARRAY['juego','exterior','agilidad','corporalidad','sociabilidad']::text[],
        '{"areas": ["corporalidad", "sociabilidad"], "lugares": ["Exterior", "campo abierto"], "cantidad": "06 participantes", "duracion": "15 minutos", "unidades": ["manada", "compañía", "tropa"], "descargas": [], "objetivos": ["Facilitar el contacto inicial", "Estimular la capacidad de reacción", "Estimular la agilidad", "Facilitar el conocimiento entre los pares"], "materiales": ["Pelota", "Balón"], "variaciones": "<b>Variación con Dos Balones:</b> Se introducen dos pelotas de diferente color al centro para exigir doble atención y llamados cruzados.<br><b>Variación con Desplazamiento en Pañolín:</b> Quien corra al centro debe llevar un pañolín en la mano y entregarlo al jugador que nombra.", "recomendaciones": "<b>Terreno Seguro:</b> Asegurar que el suelo del círculo esté libre de piedras o tropezones para las carreras cortas.<br><b>Inclusión Dirigente:</b> Velar porque ningún scout se quede sin recibir llamados durante la ronda.", "justificacion_areas": "Este juego ejercita de manera directa y dinámica las áreas de Corporalidad y Sociabilidad al estimular la coordinación psicomotriz, los reflejos rápidos y el desarrollo cardiovascular, mientras fomenta el conocimiento inicial entre los pares, la memorización de nombres y la integración activa de todos los participantes en un ambiente de sana convivencia scout.", "objetivos_educativos": [{"id": "a0c0e5c9-aba9-43be-8ce2-53bc4ede06b5", "area": "Corporalidad", "texto": "Me gusta practicar deportes.", "unidad": "Manada", "como_se_cumple": "Participando con entusiasmo en los lanzamientos y desplazamientos rápidos durante el juego."}, {"id": "5d2d48ed-c461-4a8e-9048-cceecd3de2e2", "area": "Corporalidad", "texto": "Me gusta jugar con otros niños y niñas y respeto las reglas de los juegos.", "unidad": "Manada", "como_se_cumple": "Respetando los turnos y las reglas de atrapar la pelota antes del bote."}, {"id": "1427451e-b8b3-493b-8525-e53298381e07", "area": "Corporalidad", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "unidad": "Compañía", "como_se_cumple": "Demostrando destreza física y respeto por las normas del círculo de juego."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "unidad": "Compañía", "como_se_cumple": "Esforzándome por reaccionar con mayor agilidad en cada llamado."}, {"id": "0765469b-caef-4457-9d6b-cb739c855402", "area": "Corporalidad", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "unidad": "Tropa", "como_se_cumple": "Ejercitando los reflejos motoros al correr hacia el centro para recibir el balón."}, {"id": "08369c53-2c02-4e9c-8bb5-f949cd092c98", "area": "Corporalidad", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "unidad": "Tropa", "como_se_cumple": "Manteniendo la atención alerta y coordinando los movimientos de carrera corta."}, {"id": "cfa10133-c25c-4deb-aebe-a00f8fe3f7ef", "area": "Sociabilidad", "texto": "Comparto lo que tengo con mis compañeros y compañeras.", "unidad": "Manada", "como_se_cumple": "Incluyendo alegremente a todos los lobatos al nombrar a quienes aún no han participado."}, {"id": "5cbe35dc-d15b-4070-9a36-5b0e652c7946", "area": "Sociabilidad", "texto": "Respeto las opiniones de los demás.", "unidad": "Manada", "como_se_cumple": "Integrando a todos los compañeros de seiscena sin exclusiones."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "unidad": "Compañía", "como_se_cumple": "Garantizando que todas las integrantes de la patrulla reciban un llamado de pase."}, {"id": "ea86ecee-b201-4a49-be9d-4e55de7ffe8c", "area": "Sociabilidad", "texto": "Respeto a todas las personas, independientemente de sus ideas, su clase social y su forma de vida.", "unidad": "Compañía", "como_se_cumple": "Favoreciendo la integración de miembros nuevos nombrándolos en el juego."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "unidad": "Tropa", "como_se_cumple": "Fomentando un clima fraterno de camaradería y risas en la tropa."}, {"id": "9e3ce0d2-2b56-4d1e-9135-029cfaaa0e6b", "area": "Sociabilidad", "texto": "Respeto a todas las personas, independientemente de sus ideas, su clase social y su forma de vida.", "unidad": "Tropa", "como_se_cumple": "Promoviendo el compañerismo y la buena acogida de todos en el círculo."}]}'::jsonb,
        '2026-07-27T23:45:51.910732+00:00',
        NOW()
    )
