    -- --------------------------------------------------------------------------
    -- Artículo: El Pincel Colectivo (ID: ba5d305d-e998-4fc9-8df7-d8b60b4e3354)
    -- --------------------------------------------------------------------------
    INSERT INTO articulos (id, autor_id, categoria_id, titulo, slug, contenido, extracto, imagen_destacada, estado, etiquetas, metadata, created_at, updated_at)
    VALUES (
        'ba5d305d-e998-4fc9-8df7-d8b60b4e3354',
        target_admin_id,
        NULL,
        'El Pincel Colectivo',
        'el-pincel-colectivo',
        '<h2>📜 Descripción de El Pincel Colectivo</h2><p> </p><p><strong>El Pincel Colectivo</strong> es un juego de relevos cooperativos y expresión artística diseñado para fortalecer la integración en la seiscena o patrulla. Cada equipo trabaja sobre un pliego de papel a distancia, donde sus integrantes se turnan velozmente en carreras de 10 segundos para añadir trazos y construir en conjunto una ilustración sobre una temática asignada.</p><p> </p><h2>🎲 ¿Cómo se juega El Pincel Colectivo?</h2><p> </p><h3>1. Disposición de Lienzos y Equipos</h3><p> </p><p>Se forman equipos de 3 a 6 participantes alineados en el punto de partida. A una distancia de 8 metros se ubica el pliego de papel o cartulina de cada equipo junto a sus marcadores.</p><p> </p><h3>2. Asignación del Tema y Comienzo</h3><p> </p><p>El dirigente anuncia una temática inspiradora (por ejemplo, ''El Campamento Scout'' o ''La Flor de Lis'') y da la señal de inicio.</p><p> </p><h3>3. Relevos Expresivos de 10 Segundos</h3><p> </p><p>El primer participante de cada fila corre hacia su lienzo, realiza sus trazos durante 10 segundos continuos, y regresa velozmente a entregar el marcador al siguiente compañero.</p><p> </p><h3>4. Presentación de la Obra Común</h3><p> </p><p>Al término del tiempo global de juego, los equipos presentan su dibujo terminado ante la unidad, compartiendo la idea que construyeron juntos.</p>',
        'Juego de relevos y expresión artística en equipo donde los participantes construyen colectivamente un dibujo sobre un lienzo común.',
        '/uploads/el-pincel-colectivo.webp',
        'publicado',
        ARRAY['juego','creatividad','carácter','relevos','cooperativo']::text[],
        '{"areas": ["creatividad", "carácter"], "lugares": ["Exterior", "campo abierto"], "cantidad": "06 participantes", "duracion": "20 minutos", "unidades": ["manada", "compañía", "tropa"], "descargas": [], "objetivos": ["Estimular la creatividad", "Trabajo en equipo", "Desarrollar el carácter mediante la cooperación", "Estimular la capacidad de reacción"], "materiales": ["Papel", "Lápices", "Marcadores"], "variaciones": "<b>Variación a Ciegas con Guía:</b> El dibujante de turno realiza los trazos con los ojos vendados mientras su patrulla le da indicaciones verbales desde el punto de partida.<br><b>Variación con Pañolín Atado:</b> Los integrantes de la pareja corren tomados de la mano unidos por un pañolín para dibujar juntos en cada relevo.", "recomendaciones": "<b>Promover la No Discriminación Artística:</b> Dirigentes y guiadoras deben enfatizar que el valor del juego radica en el esfuerzo colectivo y no en la habilidad plástica individual.<br><b>Delimitación del Lienzo:</b> Asegurar que los pliegos de papel estén bien fijos al suelo o pared.", "justificacion_areas": "Este juego ejercita de manera directa y lúdica las áreas de Creatividad y Carácter al estimular la imaginación, la expresión plástica y la toma de decisiones rápidas, mientras promueve el trabajo cooperativo en equipo, enseñando a los participantes a sumar sus aportes individuales sin egoísmo para alcanzar una meta colectiva.", "objetivos_educativos": [{"id": "e5eada78-3a2d-467e-8d15-da159b60552f", "area": "Creatividad", "texto": "Me gusta dibujar y pintar.", "unidad": "Manada", "como_se_cumple": "Expresando ideas lúdicas con trazos de colores al dibujar en el lienzo de la seiscena."}, {"id": "14b82459-ac31-4496-a875-8e9bd5666030", "area": "Creatividad", "texto": "En las actividades que hago se nota lo que pienso y siento.", "unidad": "Manada", "como_se_cumple": "Aportando creatividad colectiva al dibujo en equipo respetando el trabajo de los demás."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Sumando trazos originales para complementar la obra gráfica de la patrulla."}, {"id": "9758e4f9-728b-4435-a8a3-11fd36c5e3be", "area": "Creatividad", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "unidad": "Compañía", "como_se_cumple": "Demostrando ingenio plástico y comunicación no verbal en la composición visual."}, {"id": "39eaf1aa-f703-4fd0-a4b3-b9756dc30539", "area": "Creatividad", "texto": "Participo con entusiasmo en las actividades artísticas de mi Tropa.", "unidad": "Tropa", "como_se_cumple": "Aportando entusiasmo en la creación plástica de la patrulla durante las carreras de relevo."}, {"id": "6e910d1c-7021-49a5-9ece-637f480a1ec7", "area": "Creatividad", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "unidad": "Tropa", "como_se_cumple": "Integrando las contribuciones individuales en una ilustración scout armoniosa."}, {"id": "99c6e695-ef0b-4e36-956b-3faf15ada355", "area": "Carácter", "texto": "Escucho a los demás lobatos, a mis papás y a mis dirigentes y guiadoras.", "unidad": "Manada", "como_se_cumple": "Siguiendo las sugerencias de la seiscena para completar la idea del dibujo."}, {"id": "6b8c5fb5-6730-4c61-a332-2a7e6033bd94", "area": "Carácter", "texto": "Me llevo bien con todos los lobatos de la Manada.", "unidad": "Manada", "como_se_cumple": "Colaborando fraternalmente sin criticar los trazos de los demás lobatos."}, {"id": "81cd6596-30cd-40fe-83e8-c86bf12a21f2", "area": "Carácter", "texto": "Aprecio los consejos que me dan en mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Escuchando la estrategia gráfica propuesta por la guía de patrulla antes de correr."}, {"id": "0da6c9df-7a09-44cd-9961-e06c0173d41a", "area": "Carácter", "texto": "Ayudo a mis compañeras de patrulla a superarse.", "unidad": "Compañía", "como_se_cumple": "Apoyando con ánimo a las compañeras que les cuesta dibujar para que aporten al lienzo."}, {"id": "0969a204-e8c6-4ab6-ac4f-c777bae066df", "area": "Carácter", "texto": "Aprecio los consejos que me dan en mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Aceptando las ideas de la patrulla para lograr una obra integrada."}, {"id": "f608eb2d-613a-477a-86f9-03e769a87bf2", "area": "Carácter", "texto": "Ayudo a mis compañeros de patrulla a superarse.", "unidad": "Tropa", "como_se_cumple": "Motivando a todos los scouts a sumar su trazo sin temor al error."}]}'::jsonb,
        '2026-07-27T23:59:16.545922+00:00',
        NOW()
    )
