    -- --------------------------------------------------------------------------
    -- Artículo: La Cacería del Tótem Animal (ID: 5693326c-0c04-404e-b6a2-c0055287ee79)
    -- --------------------------------------------------------------------------
    INSERT INTO articulos (id, autor_id, categoria_id, titulo, slug, contenido, extracto, imagen_destacada, estado, etiquetas, metadata, created_at, updated_at)
    VALUES (
        '5693326c-0c04-404e-b6a2-c0055287ee79',
        target_admin_id,
        NULL,
        'La Cacería del Tótem Animal',
        'la-caceria-del-totem-animal',
        '<h2>📜 Descripción de La Cacería del Tótem Animal</h2><p> </p><p><strong>La Cacería del Tótem Animal</strong> es un apasionante gran juego nocturno de acecho, orientación auditiva y trabajo en equipo. Animadores o dirigentes se ocultan en el terreno de juego caracterizando a distintos animales totémicos, emitiendo su llamada sonora cada 30 segundos en la penumbra para que las patrullas los rastreen y capturen sus cupones de puntuación.</p><p> </p><h2>🎲 ¿Cómo se juega La Cacería del Tótem Animal?</h2><p> </p><h3>1. Despliegue de los Tótems Animados</h3><p> </p><p>Entre 5 y 8 animadores se internan en el área delimitada de bosque o campo abierto para esconderse en la penumbra. Cada tótem lleva cupones numerados de puntuación.</p><p> </p><h3>2. Señal de Llamada Sonora</h3><p> </p><p>Cada 30 segundos, cada animal totémico emite fuertemente su sonido característico (búho, lobo, ciervo, entre otros) desde su escondite para guiar la búsqueda auditiva.</p><p> </p><h3>3. Acecho y Captura por Patrullas</h3><p> </p><p>Las patrullas salen en sigilo a rastrear la procedencia de los sonidos. Al encontrar a un tótem, el primer equipo en llegar recibe el cupón de mayor puntaje.</p><p> </p><h3>4. Tregua y Reubicación</h3><p> </p><p>Tras cada captura, el animal hace sonar un silbato declarando 2 minutos de tregua para reubicarse en un nuevo escondite del terreno.</p>',
        'Juego nocturno de acecho y rastreo sonoro donde las patrullas localizan en la penumbra a los tótems animales escondidos.',
        '/uploads/la-caceria-del-totem-animal.webp',
        'publicado',
        ARRAY['juego','nocturno','acecho','corporalidad','sociabilidad']::text[],
        '{"areas": ["corporalidad", "sociabilidad"], "lugares": ["Exterior", "campo abierto"], "cantidad": "06 participantes", "duracion": "45 minutos", "unidades": ["manada", "compañía", "tropa", "avanzada"], "descargas": [], "objetivos": ["Reforzar el desarrollo de los sentidos", "Perder el miedo a la oscuridad", "Estrategia y planificación", "Trabajo en equipo"], "materiales": ["Linternas", "Silbato", "Tarjetas de Puntuación"], "variaciones": "<b>Variación de Campamento con Linternas Filtro:</b> Cada animal utiliza linterna con celofán de color para señalizar su posición durante 5 segundos antes de apagarse.<br><b>Variación con Mensaje Encriptado:</b> En lugar de cupones de puntos, cada animal entrega un fragmento de una clave o mensaje secreto que la patrulla debe armar al final.", "recomendaciones": "<b>Reconocimiento Previo del Terreno:</b> Inspeccionar de día el área de juego para marcar zonas de peligro o límites infranqueables.<br><b>Contención y Parejas de Seguridad:</b> Velar porque los niños menores nunca caminen solos en la oscuridad.", "justificacion_areas": "Este gran juego nocturno ejercita de manera directa las áreas de Corporalidad y Sociabilidad al estimular el desarrollo sensorial auditivo, la orientación espacial en la penumbra y la agilidad de movimiento en terreno natural, mientras promueve la cooperación al interior de la patrulla, la distribución estratégica de funciones y la sana competencia entre los equipos.", "objetivos_educativos": [{"id": "a0c0e5c9-aba9-43be-8ce2-53bc4ede06b5", "area": "Corporalidad", "texto": "Me gusta practicar deportes.", "unidad": "Manada", "como_se_cumple": "Ejercitando la agilidad física y la orientación en el juego nocturno."}, {"id": "5d2d48ed-c461-4a8e-9048-cceecd3de2e2", "area": "Corporalidad", "texto": "Me gusta jugar con otros niños y niñas y respeto las reglas de los juegos.", "unidad": "Manada", "como_se_cumple": "Respetando las señales de tregua y las reglas del acecho nocturno."}, {"id": "1427451e-b8b3-493b-8525-e53298381e07", "area": "Corporalidad", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "unidad": "Compañía", "como_se_cumple": "Desplazándose en sigilo y utilizando el sentido del oído para ubicar los tótems."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "unidad": "Compañía", "como_se_cumple": "Manteniendo el control del cuerpo y la rapidez de movimiento en el terreno."}, {"id": "0765469b-caef-4457-9d6b-cb739c855402", "area": "Corporalidad", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "unidad": "Tropa", "como_se_cumple": "Acomodando el ritmo de marcha al terreno boscoso durante la noche."}, {"id": "08369c53-2c02-4e9c-8bb5-f949cd092c98", "area": "Corporalidad", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "unidad": "Tropa", "como_se_cumple": "Coordinando desplazamientos nocturnos seguros en equipo."}, {"id": "bcabf6c9-087a-422b-bb4c-eea11313aaff", "area": "Corporalidad", "texto": "Acampo continuamente y lo hago en buenas condiciones técnicas.", "unidad": "Avanzada", "como_se_cumple": "Demostrando dominio de técnicas de camuflaje, acecho y orientación nocturna en terreno natural."}, {"id": "cfa10133-c25c-4deb-aebe-a00f8fe3f7ef", "area": "Sociabilidad", "texto": "Comparto lo que tengo con mis compañeros y compañeras.", "unidad": "Manada", "como_se_cumple": "Cooperando en la seiscena para encontrar los tótems sin alejarse del grupo."}, {"id": "5cbe35dc-d15b-4070-9a36-5b0e652c7946", "area": "Sociabilidad", "texto": "Respeto las opiniones de los demás.", "unidad": "Manada", "como_se_cumple": "Escuchando los consejos de los viejos lobos y compañeros durante el acecho."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "unidad": "Compañía", "como_se_cumple": "Apoyando el avance coordinado de todas las integrantes de la patrulla."}, {"id": "ea86ecee-b201-4a49-be9d-4e55de7ffe8c", "area": "Sociabilidad", "texto": "Respeto a todas las personas, independientemente de sus ideas, su clase social y su forma de vida.", "unidad": "Compañía", "como_se_cumple": "Fomentando el compañerismo y la confianza en la penumbra."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "unidad": "Tropa", "como_se_cumple": "Cuidando la seguridad y la unión de los hermanos scouts en el terreno."}, {"id": "9e3ce0d2-2b56-4d1e-9135-029cfaaa0e6b", "area": "Sociabilidad", "texto": "Respeto a todas las personas, independientemente de sus ideas, su clase social y su forma de vida.", "unidad": "Tropa", "como_se_cumple": "Trabajando en equipo y celebrando fraternalmente cada hallazgo."}, {"id": "007591fb-a2b6-4fb5-9286-acde65455f53", "area": "Sociabilidad", "texto": "Creo que todas las personas somos iguales en dignidad y eso marca mis relaciones con los demás.", "unidad": "Avanzada", "como_se_cumple": "Asumiendo el liderazgo táctico y la protección fraterna del equipo en el acecho de avanzada."}]}'::jsonb,
        '2026-07-28T00:17:13.863457+00:00',
        NOW()
    )
