    INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES ('b50797a4-7cfd-47e8-aaf5-f85627cb7f7c', '36b44b5b-601f-4d7f-a510-8266479c9da1', 'Integrándome con entusiasmo al grupo y compartiendo el juego de presentación con mis compañeros.');
    INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES ('b50797a4-7cfd-47e8-aaf5-f85627cb7f7c', 'b69188bf-2391-43c1-a885-abd1b13912be', 'Respetando las reglas de rotación de sillas y los turnos al momento de ser nombrado en el centro.');
    INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES ('b50797a4-7cfd-47e8-aaf5-f85627cb7f7c', '9f8cdd1f-20d5-47f8-92c2-a660693c348f', 'Valorando y memorizando con respeto los nombres de todos los integrantes de la unidad.');
    INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES ('b50797a4-7cfd-47e8-aaf5-f85627cb7f7c', '2394dd5b-87b9-4f3d-9cdd-a42649139782', 'Cediendo el puesto con fair play cuando mis vecinos son llamados a intercambiar posición.');
    INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES ('b50797a4-7cfd-47e8-aaf5-f85627cb7f7c', 'c41ebefe-da04-4671-a854-40d544b6366e', 'Invitando alegremente a distintas compañeras a ser mis nuevas vecinas de grupo.');
    INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES ('b50797a4-7cfd-47e8-aaf5-f85627cb7f7c', '007e85ea-2b06-48c2-8ac1-873d59643aae', 'Cumpliendo de forma ordenada las rotaciones a la derecha o izquierda según el conteo de respuestas.');
    INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES ('b50797a4-7cfd-47e8-aaf5-f85627cb7f7c', '0be7336d-2934-49dd-95c1-3d881a510463', 'Reaccionando con alegría y camaradería ante los cambios de silla durante la dinámica.');
    INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES ('b50797a4-7cfd-47e8-aaf5-f85627cb7f7c', 'de2f5693-de4b-48f1-b870-3c62be99aea8', 'Manteniendo el clima de juego limpio y de seguridad al correr hacia las sillas vacías.');
    INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES ('b50797a4-7cfd-47e8-aaf5-f85627cb7f7c', '34b68e26-4ce0-43e1-b45a-0b41336af495', 'Acogiendo con fraternidad scout a todos los compañeros al rotar de vecinos.');
    INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES ('b50797a4-7cfd-47e8-aaf5-f85627cb7f7c', '857f21bc-db3c-4e5e-bcd5-d3d331276fad', 'Aceptando democráticamente la dinamización del espacio y las instrucciones del líder.');
    INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES ('b50797a4-7cfd-47e8-aaf5-f85627cb7f7c', '3693aeed-e3ad-4ac9-878c-5874b61dc8d3', 'Disfrutando la sana competencia y respetando los turnos de juego de forma limpia.');
